      ),
      act: (bloc) {
        bloc.add(const BookmarkTapped('m1'));
        bloc.add(const BookmarkTapped('m1'));
      },
      wait: const Duration(milliseconds: 10),
      verify: (_) {
        verify(
          () => createEntryUseCase(
            any(),
            any(),
            chatMessageId: any(named: 'chatMessageId'),
            occurredAt: any(named: 'occurredAt'),
          ),
        ).called(1);
      },
